  if (row < 0 || row >= tableAvailableProviders_->rowCount()) {
    btnAddProvider_->setEnabled(false);
    btnRemoveProvider_->setEnabled(false);
    return;
  }
  auto* item = tableAvailableProviders_->item(row, 0);
